import heapq


def _ledger(data, component):
    revision_first = component in (1, 3, 5)
    original_tax = component in (3, 4)
    refunds = component in (1, 5)
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = ((event.get("revision", 0), pos) if revision_first else
               (seq, event.get("revision", 0), pos))
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(n, d=10000):
        if mode == "half_up":
            return (n + d // 2) // d
        return n // d

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax_base = raw if original_tax else net
        amount = net + rounded(tax_base * event.get("tax_bp", 0))
        if refunds and event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    roots = data.get("roots", {})
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = []
    for name in names:
        options = [-1]
        for row in packages[name]:
            version = row["version"]
            if version in blocked.get(name, []) or (name in pins and version != pins[name]):
                continue
            options.append(version)
        choices.append(options)

    best = None
    best_vector = None
    for vector in product(*choices):
        installed = {name: version for name, version in zip(names, vector) if version != -1}
        if any(name not in installed or not low <= installed[name] <= high
               for name, (low, high) in roots.items()):
            continue
        graph = {name: [] for name in installed}
        valid = True
        for name, version in installed.items():
            row = next(r for r in packages[name] if r["version"] == version)
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if target not in installed or not dep["min"] <= installed[target] <= dep["max"]:
                    valid = False
                    break
                graph[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        # Installed packages must be exactly the dependency closure of the roots.
        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            if name in graph:
                stack.extend(graph[name])
        if reachable != set(installed):
            continue

        state, done = set(), set()
        def visit(name):
            if name in state:
                return False
            if name in done:
                return True
            state.add(name)
            if any(not visit(child) for child in graph[name]):
                return False
            state.remove(name)
            done.add(name)
            return True
        if any(not visit(name) for name in graph):
            continue

        if best_vector is None or vector > best_vector:
            best_vector = vector
            best = installed
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    available = [job for job in jobs if job["id"] not in blocked]
    best_value = None
    best_ids = None
    for subset in combinations(available, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        events = []
        for job in subset:
            events.append((job["start"], 1))
            events.append((job["end"], -1))
        active = maximum = 0
        for _, delta in sorted(events):  # -1 end events precede +1 starts
            active += delta
            maximum = max(maximum, active)
        if maximum > 2:
            continue
        value = sum(job["value"] for job in subset)
        sorted_ids = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and sorted_ids < best_ids)):
            best_value, best_ids = value, sorted_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _routes(data):
    required = data.get("required", [])
    indexes = {node: i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    start_mask = 1 << indexes[source] if source in indexes else 0
    start_state = (source, start_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"], source, start_mask, data["coupons"])]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            durations = [(edge["duration"], remaining)]
            if remaining:
                discounted = max(2, edge["duration"] - edge.get("discount", 0))
                durations.append((discounted, remaining - 1))
            for duration, next_remaining in durations:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                dest = edge["v"]
                next_mask = mask | (1 << indexes[dest] if dest in indexes else 0)
                next_state = (dest, next_mask, next_remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, dest, next_mask, next_remaining))
    return {"arrival": None}


